const POSTS_PER_PAGE = 6;
let activeCategory = 'all';
let visibleCount = POSTS_PER_PAGE;
let searchQuery = '';

// ── Render ───────────────────────────────────────────
function createPostCard(post) {
  const tag = post.category === 'General' ? 'Engineering' : post.category;
  return `
    <div class="post-card" data-category="${post.category}" data-title="${post.title.toLowerCase()}" data-excerpt="${post.excerpt.toLowerCase()}">
      <span class="post-tag">${tag}</span>
      <div class="post-date">${post.date}</div>
      <h3>${post.title}</h3>
      <p>${post.excerpt}</p>
      <div class="post-author">${post.author}</div>
    </div>
  `;
}

function renderGrid(posts, limit) {
  const grid = document.getElementById('postGrid');
  const noResults = document.getElementById('noResults');
  const showMoreWrap = document.getElementById('showMoreWrap');

  const visiblePosts = posts.slice(0, limit);
  grid.innerHTML = visiblePosts.map(createPostCard).join('');

  if (posts.length === 0) {
    noResults.classList.add('show');
    showMoreWrap.style.display = 'none';
  } else {
    noResults.classList.remove('show');
    showMoreWrap.style.display = limit < posts.length ? 'block' : 'none';
  }
}

function filterPosts() {
  let filtered = allPosts;

  if (activeCategory !== 'all') {
    filtered = filtered.filter(p => p.category === activeCategory);
  }

  if (searchQuery.trim()) {
    const q = searchQuery.toLowerCase().trim();
    filtered = filtered.filter(p =>
      p.title.toLowerCase().includes(q) ||
      p.excerpt.toLowerCase().includes(q) ||
      p.category.toLowerCase().includes(q) ||
      p.author.toLowerCase().includes(q)
    );
  }

  visibleCount = Math.min(POSTS_PER_PAGE, filtered.length);
  renderGrid(filtered, visibleCount);

  // Update "Show more" button handler
  document.getElementById('showMoreBtn').onclick = function() {
    visibleCount = Math.min(visibleCount + POSTS_PER_PAGE, filtered.length);
    renderGrid(filtered, visibleCount);
  };
}

// ── Category Pills ───────────────────────────────────
document.getElementById('categoryPills').addEventListener('click', function(e) {
  const pill = e.target.closest('.pill');
  if (!pill) return;

  document.querySelectorAll('.pill').forEach(p => p.classList.remove('active'));
  pill.classList.add('active');
  activeCategory = pill.dataset.category;
  filterPosts();
});

// ── Search ───────────────────────────────────────────
document.getElementById('searchInput').addEventListener('input', function(e) {
  searchQuery = e.target.value;
  filterPosts();
});

// ── Mega Menus ──────────────────────────────────────
const overlay = document.getElementById('overlay');
const productsMenu = document.getElementById('productsMenu');
const resourcesMenu = document.getElementById('resourcesMenu');
let openMenu = null;

function closeMenus() {
  productsMenu.classList.remove('open');
  resourcesMenu.classList.remove('open');
  overlay.classList.remove('show');
  document.querySelectorAll('[data-menu]').forEach(b => {
    b.classList.remove('active');
    b.setAttribute('aria-expanded', 'false');
  });
  openMenu = null;
}

document.getElementById('mainNav').addEventListener('click', function(e) {
  const btn = e.target.closest('[data-menu]');
  if (!btn) return;
  e.preventDefault();

  const menuId = btn.dataset.menu;
  if (openMenu === menuId) {
    closeMenus();
    return;
  }

  closeMenus();
  const targetMenu = menuId === 'products' ? productsMenu : resourcesMenu;
  targetMenu.classList.add('open');
  overlay.classList.add('show');
  btn.classList.add('active');
  btn.setAttribute('aria-expanded', 'true');
  openMenu = menuId;
});

overlay.addEventListener('click', closeMenus);

// Close menus on Escape
